CREATE OR REPLACE FUNCTION get_row_count(p_table_name TEXT, p_status TEXT)
RETURNS BIGINT AS $$
DECLARE
    v_count BIGINT;
BEGIN
    -- %I safely quotes SQL identifiers; $1 binds parameters
    EXECUTE format('SELECT count(*) FROM %I WHERE status = $1', p_table_name)
    INTO v_count
    USING p_status;

    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION find_by_column(
    p_table  text,
    p_column text,
    p_value  text
)
RETURNS SETOF record
LANGUAGE plpgsql
AS $$
DECLARE
    query text;
BEGIN
    query := format(
        'SELECT * FROM %I WHERE %I = $1',
        p_table,
        p_column
    );

    RETURN QUERY EXECUTE query USING p_value;
END $$;

-- Call with an explicit row shape
SELECT *
FROM find_by_column('customers', 'email', 'ada@example.com')
    AS c(id int, email text, name text);
